                continue
            if not COMP_RE.search(span):
                continue
            total += 1
            if norm_str(s.get("pred_code")) == UNKNOWN:
                unk += 1

    if total < 50:
        return

    rate = unk / total
    assert rate <= 0.25, f"Too many UNKNOWN when component refs exist: {rate:.2%} (need ≤ 25%)"


